## Workflow D — General-purpose Knowledge Retrieval Tool

Designed to be callable from ANY agent project, not just this Sales Agent — input/output contract deliberately has no sales/CRM-specific fields.

Reuses the real, proven embedding + Qdrant logic from '1 - Query Processing' (Gemini gemini-embedding-001, same Qdrant payload shape, same threshold-status pattern).

Deliberately does NOT include a final LLM answer-composition step (unlike the original '2 - Context Optimization Engine', which ends in a Basic LLM Chain) — the calling agent composes the reply itself. This tool's job stops at: relevant chunks, or an explicit no-match signal.

INPUT: { query: string, top_k?: number (default 5), filters?: object }
OUTPUT: { found: boolean, chunks: [{ text, source_file, section_title, score }], chunk_count, best_score, status }

parameters.jsCode:
// Input validation — same pattern as your existing 'Validate Request' node,
// generalized: no company/department/customer fields, since this is meant
// to be reusable across unrelated projects.
const input = $json;

if (!input.query || typeof input.query !== 'string' || input.query.trim().length === 0) {
  return { json: { valid: false, error: 'query is required and must be a non-empty string' } };
}

let topK = input.top_k;
if (topK === undefined || topK === null || topK === '') {
  topK = 5;
}
topK = parseInt(topK, 10);
if (isNaN(topK) || topK < 1) topK = 5;
if (topK > 20) topK = 20; // safety ceiling — a tool call shouldn't return an unbounded chunk set

return {
  json: {
    valid: true,
    query: input.query.trim(),
    top_k: topK,
    filters: input.filters || {}
  }
};

// Threshold + generic metadata filtering + dedup + adjacent-chunk merge/compress + final formatting.
// Reuses proven threshold default (0.50), and the dedup/merge/compress logic
// from the existing Context Optimization Engine, adapted for Workflow D's simpler contract.
// Deliberately NOT included here (deferred, per project decision): composite ranking/diversity,
// query-complexity-based dynamic budgeting — see project notes.
const MIN_SCORE = 0.50;
const topInput = $('Validate Input').item.json;
const filters = topInput.filters || {};

const points = $json.result?.points || [];

function compressText(text, sectionTitle) {
  if (!text) return '';
  let result = text.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (sectionTitle) {
    const titleIndex = result.indexOf(sectionTitle);
    if (titleIndex !== -1) {
      const secondOccurrence = result.indexOf(sectionTitle, titleIndex + sectionTitle.length);
      if (secondOccurrence !== -1) {
        result = result.slice(0, secondOccurrence) + result.slice(secondOccurrence + sectionTitle.length);
        result = result.replace(/\n{3,}/g, '\n\n').trim();
      }
    }
  }
  return result;
}

// Merges runs of consecutive chunk_index values within the same document —
// e.g. a package's pricing details split across two adjacent chunks come
// back as one coherent block instead of two disjointed ones.
function mergeAdjacentChunks(chunks) {
  const byDocument = new Map();
  for (const chunk of chunks) {
    const key = chunk.document_uuid ?? 'unknown';
    if (!byDocument.has(key)) byDocument.set(key, []);
    byDocument.get(key).push(chunk);
  }

  const merged = [];
  for (const group of byDocument.values()) {
    group.sort((a, b) => (a.chunk_index ?? 0) - (b.chunk_index ?? 0));
    let current = null;
    for (const chunk of group) {
      const isAdjacent =
        current !== null &&
        typeof chunk.chunk_index === 'number' &&
        typeof current._lastChunkIndex === 'number' &&
        chunk.chunk_index === current._lastChunkIndex + 1;

      if (isAdjacent) {
        current.text = `${current.text}\n\n${chunk.text ?? ''}`.trim();
        current.score = Math.max(current.score, chunk.score ?? 0);
        current._lastChunkIndex = chunk.chunk_index;
      } else {
        if (current) merged.push(current);
        current = { ...chunk, text: chunk.text ?? '', _lastChunkIndex: chunk.chunk_index };
      }
    }
    if (current) merged.push(current);
  }
  return merged;
}

let status;
if (points.length === 0) {
  status = 'EMPTY_COLLECTION';
} else {
  const aboveThreshold = points.filter(p => (p.score ?? 0) >= MIN_SCORE);

  let filtered = aboveThreshold;
  const filterKeys = Object.keys(filters);
  if (filterKeys.length > 0) {
    filtered = aboveThreshold.filter(p =>
      filterKeys.every(key => p.payload && p.payload[key] === filters[key])
    );
  }

  if (filtered.length === 0) {
    status = 'NO_MATCH';
  } else {
    // 1. Dedup by chunk_uuid — Qdrant's own overlapping chunking can otherwise return the same chunk twice.
    const seen = new Set();
    const deduped = filtered.filter(p => {
      const uuid = p.payload?.chunk_uuid;
      if (!uuid || seen.has(uuid)) return uuid ? false : true; // keep if no uuid to key on, dedup if present
      seen.add(uuid);
      return true;
    });

    // 2. Map to a plain working shape carrying what merge/compress needs.
    const mapped = deduped.map(p => ({
      text: p.payload?.text || '',
      source_file: p.payload?.file_name || null,
      section_title: p.payload?.section_title || null,
      score: p.score ?? 0,
      document_uuid: p.payload?.document_uuid || null,
      chunk_index: p.payload?.chunk_index
    }));

    // 3. Merge adjacent chunks within the same document.
    const merged = mergeAdjacentChunks(mapped);

    // 4. Compress merged text.
    for (const chunk of merged) {
      chunk.text = compressText(chunk.text, chunk.section_title);
    }

    // 5. Final sort by score, strip internal-only fields before returning.
    const chunks = merged
      .sort((a, b) => b.score - a.score)
      .map(({ text, source_file, section_title, score }) => ({ text, source_file, section_title, score }));

    return {
      json: {
        found: true,
        chunks,
        chunk_count: chunks.length,
        best_score: chunks[0].score,
        status: 'SUCCESS'
      }
    };
  }
}

return { json: { found: false, chunks: [], chunk_count: 0, best_score: 0, status } };
